		<div class="brazilts-blk elementor-element elementor-element-0b533e9 e-flex e-con-boxed e-con e-parent" data-id="0b533e9" data-element_type="container" data-e-type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;}">
